import { Skeleton, type SkeletonProps } from '@/components/ui/skeleton'
export interface SkeletonPlusProps {
  type?: 'dashboard' | 'list' | 'form' | 'table' | 'chart'
  rows?: number
  animated?: boolean
  animation?: SkeletonProps['animation']
}
export function SkeletonPlus({
  type = 'dashboard',
  rows = 4,
  animated = true,
  animation = 'wave',
}: SkeletonPlusProps) {
  const skeletonProps = { animated, animation }
  return (
    <div role="status" aria-label="Loading content" className="space-y-5">
      <Skeleton {...skeletonProps} className="h-5 w-40" />
      {type === 'chart' && (
        <div className="flex h-48 items-end gap-3 rounded-lg border p-4">
          {Array.from({ length: rows }, (_, i) => (
            <Skeleton
              {...skeletonProps}
              key={i}
              className="flex-1"
              style={{ height: `${30 + ((i * 37) % 70)}%` }}
            />
          ))}
        </div>
      )}
      {type === 'table' && (
        <div className="overflow-hidden rounded-lg border">
          {Array.from({ length: rows + 1 }, (_, i) => (
            <div key={i} className="flex gap-4 border-b p-4">
              {[1, 2, 3, 4].map((n) => (
                <Skeleton {...skeletonProps} key={n} className="h-3 flex-1" />
              ))}
            </div>
          ))}
        </div>
      )}
      {type === 'dashboard' && (
        <div className="grid grid-cols-3 gap-3">
          {[1, 2, 3].map((i) => (
            <Skeleton {...skeletonProps} key={i} className="h-24 rounded-xl" />
          ))}
        </div>
      )}
      {type !== 'table' &&
        type !== 'chart' &&
        Array.from({ length: rows }, (_, i) => (
          <div key={i} className="flex items-center gap-3">
            {type === 'list' && (
              <Skeleton {...skeletonProps} className="size-10 shrink-0 rounded-full" />
            )}
            <div className="flex-1 space-y-2">
              <Skeleton {...skeletonProps} className="h-3 w-1/3" />
              <Skeleton
                {...skeletonProps}
                className={type === 'form' ? 'h-9 w-full' : 'h-3 w-3/4'}
              />
            </div>
          </div>
        ))}
    </div>
  )
}

import { cn } from '@/lib/utils'

export interface SkeletonProps extends React.ComponentProps<'div'> {
  animated?: boolean
  animation?: 'wave' | 'pulse'
  type?: 'text' | 'avatar' | 'button' | 'input' | 'image' | 'card'
  rows?: number
}

function Skeleton({
  className,
  animated = true,
  animation = 'wave',
  type,
  rows = 3,
  ...props
}: SkeletonProps) {
  if (type === 'text')
    return (
      <div className={cn('space-y-3', className)} {...props}>
        {Array.from({ length: rows }, (_, index) => (
          <Skeleton
            key={index}
            animated={animated}
            animation={animation}
            className="h-3"
            style={{ width: index === rows - 1 ? '70%' : '100%' }}
          />
        ))}
      </div>
    )
  return (
    <>
      {animated && animation === 'wave' && (
        <style
          href="ergonui-skeleton-wave"
          precedence="components"
        >{`@keyframes ergon-skeleton-wave { from { transform: translateX(-100%); } to { transform: translateX(100%); } }`}</style>
      )}
      <div
        data-slot="skeleton"
        data-animation={animated ? animation : 'none'}
        className={cn(
          'relative overflow-hidden rounded-md bg-accent motion-reduce:animate-none',
          animated && animation === 'pulse' && 'animate-pulse',
          animated &&
            animation === 'wave' &&
            "after:pointer-events-none after:absolute after:inset-0 after:animate-[ergon-skeleton-wave_1.8s_ease-in-out_infinite] after:bg-linear-to-r after:from-transparent after:via-muted-foreground/15 after:to-transparent after:content-[''] motion-reduce:after:animate-none",
          type === 'avatar'
            ? 'size-12 rounded-full'
            : type === 'button'
              ? 'h-9 w-24'
              : type === 'input'
                ? 'h-9 w-full'
                : type === 'image'
                  ? 'aspect-video w-full'
                  : type === 'card'
                    ? 'h-40 w-full'
                    : '',
          className,
        )}
        {...props}
      />
    </>
  )
}

export { Skeleton }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
